def replace_text_in_paragraph(p: etree._Element, replacements: List[Tuple[str, str]]) -> bool:
    """Apply replacements inside a paragraph.

    Strategy:
    1) Try per-run replacement (safe when old/new occur wholly inside one <hp:t>).
    2) If nothing changed but the OLD value exists across run boundaries,
       rewrite the paragraph to a single run with the fully replaced text.

    Returns True if any text changed.
    """
    # 1) Per-run replacement
    changed = False
    for t in p.xpath('.//hp:t', namespaces=NS):
        if t.text is None:
            continue
        original = t.text
        new = original
        for old, newv in replacements:
            if old and old in new:
                new = new.replace(old, newv)
        if new != original:
            t.text = new
            changed = True

    if changed:
        return True

    # 2) Cross-run replacement fallback
    full_before = paragraph_text(p)
    full_after = full_before
    for old, newv in replacements:
        if old and old in full_after:
            full_after = full_after.replace(old, newv)

    if full_after != full_before:
        # Rewriting the paragraph is the simplest robust option when a token is
        # split across multiple <hp:t> runs (e.g., 'Northwind ' + 'Retail').
        return set_paragraph_to_single_run(p, full_after)

    return False

